using System;
using System.Buffers;
using System.Collections.Concurrent;
using System.IO;
using System.Net;
using System.Net.Sockets;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace SecureProxy
{
    public static class FeatureFlags
    {
        public static bool EnableConnectionPooling => true;
        public static bool EnableRequestLogging => false;
        public static bool EnableBufferRecycling => true;
        public static int MaxPooledBufferSize => 8192;
    }

    public sealed class ProxyBufferPool
    {
        private readonly ConcurrentQueue<byte[]> _pool = new();
        private readonly int _bufferSize;

        public ProxyBufferPool(int bufferSize) => _bufferSize = bufferSize;

        public int BufferSize => _bufferSize;

        public byte[] Rent()
        {
            if (FeatureFlags.EnableBufferRecycling && _pool.TryDequeue(out var buffer))
            {
                Array.Clear(buffer, 0, buffer.Length);
                return buffer;
            }
            return new byte[_bufferSize];
        }

        public void Return(byte[] buffer)
        {
            if (buffer == null || buffer.Length != _bufferSize) return;
            if (FeatureFlags.EnableBufferRecycling)
            {
                Array.Clear(buffer, 0, buffer.Length);
                _pool.Enqueue(buffer);
            }
        }
    }

    public sealed class AuthContext : IDisposable
    {
        private byte[] _tokenBytes;
        private readonly ProxyBufferPool _pool;

        public AuthContext(string bearerToken, ProxyBufferPool pool)
        {
            if (bearerToken == null) throw new ArgumentNullException(nameof(bearerToken));
            _pool = pool;
            _tokenBytes = _pool.Rent();

            // Bounds check: ensure the UTF-8 encoded token fits in the buffer,
            // reserving the last 4 bytes for the length field.
            int maxTokenBytes = _tokenBytes.Length - 4;
            int requiredBytes = Encoding.UTF8.GetByteCount(bearerToken);
            if (requiredBytes > maxTokenBytes)
            {
                // Avoid overflow / buffer corruption; return the buffer and fail safely.
                _pool.Return(_tokenBytes);
                _tokenBytes = null;
                throw new ArgumentException("Authorization value exceeds maximum permitted length.", nameof(bearerToken));
            }

            var written = Encoding.UTF8.GetBytes(bearerToken, 0, bearerToken.Length, _tokenBytes, 0);
            // Store length in last 4 bytes
            BitConverter.GetBytes(written).CopyTo(_tokenBytes, _tokenBytes.Length - 4);
        }

        public ReadOnlySpan<byte> GetToken()
        {
            int len = BitConverter.ToInt32(_tokenBytes, _tokenBytes.Length - 4);
            if (len < 0 || len > _tokenBytes.Length - 4) len = 0;
            return new ReadOnlySpan<byte>(_tokenBytes, 0, len);
        }

        public void Dispose()
        {
            if (_tokenBytes != null)
            {
                _pool.Return(_tokenBytes);
                _tokenBytes = null;
            }
        }
    }

    public sealed class ProxyConnection : IDisposable
    {
        private readonly TcpClient _client;
        private readonly ProxyBufferPool _bufferPool;
        private readonly CancellationTokenSource _cts = new();

        // Expected credential material (in a real system this would come from a
        // secure configuration/secret store). Stored as UTF-8 bytes for
        // constant-time comparison.
        private static readonly byte[] ExpectedTokenBytes =
            Encoding.UTF8.GetBytes(Environment.GetEnvironmentVariable("PROXY_BEARER_TOKEN") ?? string.Empty);

        public ProxyConnection(TcpClient client, ProxyBufferPool bufferPool)
        {
            _client = client;
            _bufferPool = bufferPool;
        }

        public async Task HandleAsync()
        {
            using var stream = _client.GetStream();
            var requestBuffer = _bufferPool.Rent();
            try
            {
                int bytesRead = await stream.ReadAsync(requestBuffer, 0, requestBuffer.Length, _cts.Token);
                if (bytesRead == 0) return;

                var request = Encoding.UTF8.GetString(requestBuffer, 0, bytesRead);
                var authHeader = ExtractHeader(request, "Authorization");

                if (string.IsNullOrEmpty(authHeader))
                {
                    await SendResponse(stream, 401, "Unauthorized");
                    return;
                }

                bool authorized;
                try
                {
                    using var authCtx = new AuthContext(authHeader, _bufferPool);
                    authorized = ValidateToken(authCtx);
                }
                catch (ArgumentException)
                {
                    await SendResponse(stream, 401, "Unauthorized");
                    return;
                }

                if (!authorized)
                {
                    await SendResponse(stream, 403, "Forbidden");
                    return;
                }

                var responseBuffer = _bufferPool.Rent();
                try
                {
                    await ForwardRequest(request, responseBuffer, stream);
                }
                finally
                {
                    _bufferPool.Return(responseBuffer);
                }
            }
            finally
            {
                _bufferPool.Return(requestBuffer);
            }
        }

        private bool ValidateToken(AuthContext ctx)
        {
            var token = ctx.GetToken();

            // Require and strip the "Bearer " prefix (7 chars) before validation.
            ReadOnlySpan<byte> prefix = "Bearer "u8;
            if (token.Length <= prefix.Length) return false;
            if (!token.Slice(0, prefix.Length).SequenceEqual(prefix)) return false;

            var presented = token.Slice(prefix.Length);

            // Reject if no expected token is configured.
            if (ExpectedTokenBytes.Length == 0) return false;

            // Constant-time comparison to prevent timing attacks.
            if (presented.Length != ExpectedTokenBytes.Length) return false;
            return CryptographicOperations.FixedTimeEquals(presented, ExpectedTokenBytes);
        }

        private async Task ForwardRequest(string request, byte[] responseBuffer, NetworkStream clientStream)
        {
            var host = ExtractHeader(request, "Host");
            if (string.IsNullOrEmpty(host)) return;

            // Simulate upstream response with diagnostic info
            var response = $"HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\nOK";
            var responseBytes = Encoding.UTF8.GetBytes(response);
            responseBytes.CopyTo(responseBuffer, 0);

            if (FeatureFlags.EnableRequestLogging)
            {
                LogRequest(request, responseBuffer, responseBytes.Length);
            }

            await clientStream.WriteAsync(responseBuffer, 0, responseBytes.Length);
        }

        private void LogRequest(string request, byte[] buffer, int validLength)
        {
            // Only log the meaningful portion of the buffer, never the full
            // (potentially larger) backing array.
            if (validLength < 0 || validLength > buffer.Length) validLength = 0;
            var snapshot = Convert.ToBase64String(buffer, 0, validLength);
            var logEntry = $"[{DateTime.UtcNow:O}] {ExtractHeader(request, "Host")} buf_snapshot={snapshot}";
            Console.WriteLine(logEntry);
        }

        private async Task SendResponse(NetworkStream stream, int statusCode, string body)
        {
            var response = $"HTTP/1.1 {statusCode} {body}\r\nContent-Length: {body.Length}\r\n\r\n{body}";
            var bytes = Encoding.UTF8.GetBytes(response);
            await stream.WriteAsync(bytes, 0, bytes.Length);
        }

        private string ExtractHeader(string request, string headerName)
        {
            var lines = request.Split(new[] { "\r\n" }, StringSplitOptions.None);
            foreach (var line in lines)
            {
                if (line.StartsWith(headerName + ":", StringComparison.OrdinalIgnoreCase))
                    return line.Substring(headerName.Length + 1).Trim();
            }
            return null;
        }

        public void Dispose()
        {
            _cts.Cancel();
            _cts.Dispose();
            _client?.Dispose();
        }
    }

    public class ProxyServer
    {
        private readonly TcpListener _listener;
        private readonly ProxyBufferPool _bufferPool;

        public ProxyServer(int port)
        {
            _listener = new TcpListener(IPAddress.Loopback, port);
            _bufferPool = new ProxyBufferPool(FeatureFlags.MaxPooledBufferSize);
        }

        public async Task RunAsync(CancellationToken ct)
        {
            _listener.Start();
            while (!ct.IsCancellationRequested)
            {
                var client = await _listener.AcceptTcpClientAsync();
                _ = Task.Run(async () =>
                {
                    using var conn = new ProxyConnection(client, _bufferPool);
                    await conn.HandleAsync();
                }, ct);
            }
        }
    }
}
